-- Institution-scoped lifecycle for the Shadecode platform.
-- All writes occur through SECURITY DEFINER RPCs after server-side identity and
-- tenant-role checks. No authenticated table-write policies are added.
-- The invite code is generated by a trusted server route; only its SHA-256 digest
-- is persisted. A redeemed invite is single-use and bound to auth.uid().

create table if not exists public.platform_institution_invites (
  id uuid primary key default gen_random_uuid(),
  institution_id uuid not null references public.platform_institutions(id) on delete cascade,
  group_id uuid references public.platform_groups(id) on delete cascade,
  code_hash text not null unique,
  membership_role text not null check (membership_role in
    ('student','teacher','parent','guardian','tutor','administrator','staff','content_author')),
  expires_at timestamptz not null,
  created_by uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now(),
  redeemed_by uuid references auth.users(id) on delete set null,
  redeemed_at timestamptz,
  revoked_at timestamptz,
  constraint platform_institution_invites_hash_check check (code_hash ~ '^[0-9a-f]{64}$'),
  constraint platform_institution_invites_expiry_check check (expires_at > created_at)
);

create index if not exists platform_institution_invites_institution_idx
  on public.platform_institution_invites(institution_id, created_at desc);

create table if not exists public.platform_membership_audit (
  id uuid primary key default gen_random_uuid(),
  institution_id uuid not null references public.platform_institutions(id) on delete cascade,
  actor_user_id uuid references auth.users(id) on delete set null,
  target_user_id uuid references auth.users(id) on delete set null,
  action text not null,
  entity_type text not null check (entity_type in ('institution','group','institution_member','group_member','invite')),
  entity_id uuid,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists platform_membership_audit_institution_created_idx
  on public.platform_membership_audit(institution_id, created_at desc);

alter table public.platform_institution_invites enable row level security;
alter table public.platform_membership_audit enable row level security;

-- These records are intentionally not directly readable/writable through the
-- browser PostgREST role. Authorized server RPCs are the only access path.
revoke all on public.platform_institution_invites from public, anon, authenticated;
revoke all on public.platform_membership_audit from public, anon, authenticated;

create or replace function public.create_platform_institution(
  p_name text,
  p_institution_type text default 'school',
  p_country_code text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_institution_id uuid;
begin
  if v_actor is null or not public.has_role(v_actor, 'admin'::text) then
    raise exception 'platform institution bootstrap requires a platform administrator' using errcode = '42501';
  end if;
  if p_name is null or length(btrim(p_name)) not between 2 and 160 then
    raise exception 'institution name must be between 2 and 160 characters' using errcode = '22023';
  end if;
  if p_institution_type not in ('school','university','polytechnic','college','tvet','vocational','training','organization') then
    raise exception 'unsupported institution type' using errcode = '22023';
  end if;
  if p_country_code is not null and p_country_code !~ '^[A-Z]{2}$' then
    raise exception 'country code must be ISO alpha-2' using errcode = '22023';
  end if;

  insert into public.platform_institutions(name,institution_type,country_code)
  values (btrim(p_name),p_institution_type,p_country_code)
  returning id into v_institution_id;

  insert into public.platform_institution_members(institution_id,user_id,membership_role,status)
  values (v_institution_id,v_actor,'administrator','active');

  insert into public.platform_membership_audit(institution_id,actor_user_id,target_user_id,action,entity_type,entity_id)
  values (v_institution_id,v_actor,v_actor,'institution.created','institution',v_institution_id);

  return v_institution_id;
end;
$$;

create or replace function public.create_platform_group(
  p_institution_id uuid,
  p_name text,
  p_group_type text default 'class',
  p_parent_group_id uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_group_id uuid;
begin
  if v_actor is null then
    raise exception 'active institution administrator required' using errcode = '42501';
  end if;
  perform 1 from public.platform_institutions where id=p_institution_id for update;
  if not found or not exists (
    select 1 from public.platform_institution_members m
    where m.institution_id=p_institution_id and m.user_id=v_actor
      and m.status='active' and m.membership_role='administrator'
  ) then
    raise exception 'active institution administrator required' using errcode = '42501';
  end if;
  if p_name is null or length(btrim(p_name)) not between 1 and 120 then
    raise exception 'group name must be between 1 and 120 characters' using errcode = '22023';
  end if;
  if p_group_type not in ('class','cohort','department','programme','course','club','study_group','other') then
    raise exception 'unsupported group type' using errcode = '22023';
  end if;
  if p_parent_group_id is not null and not exists (
    select 1 from public.platform_groups
    where id=p_parent_group_id and institution_id=p_institution_id
  ) then
    raise exception 'parent group must belong to the same institution' using errcode = '22023';
  end if;

  insert into public.platform_groups(institution_id,parent_group_id,name,group_type)
  values (p_institution_id,p_parent_group_id,btrim(p_name),p_group_type)
  returning id into v_group_id;

  insert into public.platform_membership_audit(institution_id,actor_user_id,action,entity_type,entity_id)
  values (p_institution_id,v_actor,'group.created','group',v_group_id);

  return v_group_id;
end;
$$;

create or replace function public.create_platform_institution_invite(
  p_institution_id uuid,
  p_code_hash text,
  p_membership_role text,
  p_group_id uuid default null,
  p_expires_at timestamptz default (now() + interval '14 days')
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_invite_id uuid;
begin
  if v_actor is null then
    raise exception 'active institution administrator required' using errcode = '42501';
  end if;
  perform 1 from public.platform_institutions where id=p_institution_id for update;
  if not found or not exists (
    select 1 from public.platform_institution_members m
    where m.institution_id=p_institution_id and m.user_id=v_actor
      and m.status='active' and m.membership_role='administrator'
  ) then
    raise exception 'active institution administrator required' using errcode = '42501';
  end if;
  if p_code_hash is null or p_code_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invite digest must be a SHA-256 hex digest' using errcode = '22023';
  end if;
  if p_membership_role not in ('student','teacher','parent','guardian','tutor','administrator','staff','content_author') then
    raise exception 'unsupported institution membership role' using errcode = '22023';
  end if;
  if p_expires_at <= now() or p_expires_at > now() + interval '30 days' then
    raise exception 'invite expiry must be within the next 30 days' using errcode = '22023';
  end if;
  if p_group_id is not null and not exists (
    select 1 from public.platform_groups
    where id=p_group_id and institution_id=p_institution_id
  ) then
    raise exception 'invite group must belong to the same institution' using errcode = '22023';
  end if;
  if p_group_id is not null and p_membership_role='content_author' then
    raise exception 'content_author cannot be assigned to a group' using errcode = '22023';
  end if;

  insert into public.platform_institution_invites(
    institution_id,group_id,code_hash,membership_role,expires_at,created_by
  ) values (
    p_institution_id,p_group_id,p_code_hash,p_membership_role,p_expires_at,v_actor
  ) returning id into v_invite_id;

  insert into public.platform_membership_audit(institution_id,actor_user_id,action,entity_type,entity_id,metadata)
  values (p_institution_id,v_actor,'invite.created','invite',v_invite_id,
    jsonb_build_object('membership_role',p_membership_role,'group_id',p_group_id,'expires_at',p_expires_at));

  return v_invite_id;
end;
$$;

create or replace function public.redeem_platform_institution_invite(p_code text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_invite public.platform_institution_invites%rowtype;
  v_institution_id uuid;
begin
  if v_actor is null then
    raise exception 'sign in before redeeming an institution invite' using errcode = '42501';
  end if;
  if p_code is null or length(p_code) not between 20 and 128 then
    raise exception 'invalid or expired invite' using errcode = '22023';
  end if;

  -- Resolve the tenant first, then lock it before touching the invite or
  -- membership rows. This uses the same lock order as admin revocation and
  -- prevents invite redemption racing a suspension/revocation transition.
  select i.institution_id into v_institution_id
  from public.platform_institution_invites i
  where i.code_hash=encode(sha256(convert_to(p_code,'utf8')),'hex')
    and i.redeemed_at is null and i.revoked_at is null and i.expires_at > now();
  if v_institution_id is null then
    raise exception 'invalid, expired, revoked or already redeemed invite' using errcode = '22023';
  end if;

  perform 1 from public.platform_institutions where id=v_institution_id for update;
  if not found then
    raise exception 'institution no longer exists' using errcode = '22023';
  end if;

  update public.platform_institution_invites
     set redeemed_by=v_actor, redeemed_at=now()
   where code_hash=encode(sha256(convert_to(p_code,'utf8')),'hex')
     and institution_id=v_institution_id
     and redeemed_at is null and revoked_at is null and expires_at > now()
  returning * into v_invite;

  if v_invite.id is null then
    raise exception 'invalid, expired, revoked or already redeemed invite' using errcode = '22023';
  end if;

  if exists (
    select 1 from public.platform_institution_members
    where institution_id=v_invite.institution_id and user_id=v_actor
      and status in ('suspended','revoked')
  ) then
    raise exception 'institution membership is suspended or revoked; ask an administrator to restore access' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.platform_group_members
    where group_id=v_invite.group_id and user_id=v_actor
      and status in ('suspended','revoked')
  ) then
    raise exception 'group membership is suspended or revoked; ask an administrator to restore access' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.platform_institution_members
    where institution_id=v_invite.institution_id and user_id=v_actor
      and status='active' and membership_role<>v_invite.membership_role
  ) then
    raise exception 'an active institution membership already exists with a different role' using errcode = '23505';
  end if;
  if v_invite.group_id is not null and exists (
    select 1 from public.platform_group_members
    where group_id=v_invite.group_id and user_id=v_actor
      and status='active' and membership_role<>v_invite.membership_role
  ) then
    raise exception 'an active group membership already exists with a different role' using errcode = '23505';
  end if;

  insert into public.platform_institution_members(institution_id,user_id,membership_role,status)
  values (v_invite.institution_id,v_actor,v_invite.membership_role,'active')
  on conflict (institution_id,user_id) do update
    set membership_role=excluded.membership_role,status='active',updated_at=now();

  if v_invite.group_id is not null then
    insert into public.platform_group_members(group_id,user_id,membership_role,status)
    values (v_invite.group_id,v_actor,v_invite.membership_role,'active')
    on conflict (group_id,user_id) do update
      set membership_role=excluded.membership_role,status='active',updated_at=now();
  end if;

  insert into public.platform_membership_audit(institution_id,actor_user_id,target_user_id,action,entity_type,entity_id,metadata)
  values (v_invite.institution_id,v_actor,v_actor,'invite.redeemed','invite',v_invite.id,
    jsonb_build_object('membership_role',v_invite.membership_role,'group_id',v_invite.group_id));

  return jsonb_build_object('institution_id',v_invite.institution_id,'group_id',v_invite.group_id,'membership_role',v_invite.membership_role);
end;
$$;

create or replace function public.revoke_platform_institution_invite(
  p_institution_id uuid,
  p_invite_id uuid
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
begin
  if v_actor is null then
    raise exception 'active institution administrator required' using errcode = '42501';
  end if;
  perform 1 from public.platform_institutions where id=p_institution_id for update;
  if not found or not exists (
    select 1 from public.platform_institution_members m
    where m.institution_id=p_institution_id and m.user_id=v_actor
      and m.status='active' and m.membership_role='administrator'
  ) then
    raise exception 'active institution administrator required' using errcode = '42501';
  end if;

  update public.platform_institution_invites
    set revoked_at=now()
    where id=p_invite_id and institution_id=p_institution_id
      and redeemed_at is null and revoked_at is null;
  if not found then
    raise exception 'unused institution invite not found' using errcode = 'P0002';
  end if;

  insert into public.platform_membership_audit(institution_id,actor_user_id,action,entity_type,entity_id)
  values (p_institution_id,v_actor,'invite.revoked','invite',p_invite_id);
end;
$$;

create or replace function public.set_platform_membership_status(
  p_institution_id uuid,
  p_target_user_id uuid,
  p_status text,
  p_group_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_role text;
  v_active_admins integer;
begin
  if v_actor is null then
    raise exception 'active institution administrator required' using errcode = '42501';
  end if;
  -- Serialize membership transitions for this tenant. In particular, two
  -- concurrent administrator revocations cannot both pass the last-admin check.
  perform 1 from public.platform_institutions where id=p_institution_id for update;
  if not found or not exists (
    select 1 from public.platform_institution_members m
    where m.institution_id=p_institution_id and m.user_id=v_actor
      and m.status='active' and m.membership_role='administrator'
  ) then
    raise exception 'active institution administrator required' using errcode = '42501';
  end if;
  if p_status not in ('active','suspended','revoked') then
    raise exception 'unsupported membership status' using errcode = '22023';
  end if;

  if p_group_id is null then
    select membership_role into v_role
    from public.platform_institution_members
    where institution_id=p_institution_id and user_id=p_target_user_id
    for update;
    if v_role is null then raise exception 'institution membership not found' using errcode = 'P0002'; end if;
    if v_role='administrator' and p_status <> 'active' then
      select count(*) into v_active_admins from public.platform_institution_members
      where institution_id=p_institution_id and membership_role='administrator' and status='active';
      if v_active_admins <= 1 then
        raise exception 'cannot suspend or revoke the last active institution administrator' using errcode = '23514';
      end if;
    end if;
    update public.platform_institution_members
      set status=p_status,updated_at=now()
      where institution_id=p_institution_id and user_id=p_target_user_id;

    -- Institution suspension/revocation must immediately remove every active
    -- class-level authorization too. Restoring institution membership does not
    -- silently restore group access; an administrator must explicitly reassign it.
    if p_status <> 'active' then
      update public.platform_group_members gm
        set status=p_status,updated_at=now()
        from public.platform_groups g
        where gm.group_id=g.id and g.institution_id=p_institution_id
          and gm.user_id=p_target_user_id and gm.status='active';
    end if;

    insert into public.platform_membership_audit(institution_id,actor_user_id,target_user_id,action,entity_type,entity_id,metadata)
    values (p_institution_id,v_actor,p_target_user_id,'institution_membership.'||p_status,'institution_member',p_institution_id,
      jsonb_build_object('membership_role',v_role,'group_memberships_cascaded',true));
  else
    if not exists (select 1 from public.platform_groups where id=p_group_id and institution_id=p_institution_id) then
      raise exception 'group does not belong to institution' using errcode = '22023';
    end if;
    if p_status='active' and not exists (
      select 1 from public.platform_institution_members
      where institution_id=p_institution_id and user_id=p_target_user_id and status='active'
    ) then
      raise exception 'active institution membership is required before group access can be restored' using errcode = '42501';
    end if;
    select membership_role into v_role from public.platform_group_members
      where group_id=p_group_id and user_id=p_target_user_id for update;
    if v_role is null then raise exception 'group membership not found' using errcode = 'P0002'; end if;
    update public.platform_group_members
      set status=p_status,updated_at=now()
      where group_id=p_group_id and user_id=p_target_user_id;
    insert into public.platform_membership_audit(institution_id,actor_user_id,target_user_id,action,entity_type,entity_id,metadata)
    values (p_institution_id,v_actor,p_target_user_id,'group_membership.'||p_status,'group_member',p_group_id,
      jsonb_build_object('membership_role',v_role));
  end if;
end;
$$;

drop function if exists public.list_platform_group_roster(uuid);

create function public.list_platform_group_roster(p_group_id uuid)
returns table (
  user_id uuid,
  display_name text,
  membership_role text,
  status text,
  joined_at timestamptz
)
language plpgsql
security definer
set search_path = public, pg_temp
as $roster$
declare
  v_actor uuid := auth.uid();
  v_institution_id uuid;
begin
  if v_actor is null then
    raise exception 'sign in to view a class roster' using errcode = '42501';
  end if;

  select g.institution_id into v_institution_id
  from public.platform_groups g where g.id=p_group_id;
  if v_institution_id is null then
    raise exception 'class not found' using errcode = 'P0002';
  end if;

  if not exists (
    select 1 from public.platform_institution_members im
    where im.institution_id=v_institution_id and im.user_id=v_actor and im.status='active'
  ) then
    raise exception 'active institution membership required' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.platform_institution_members im
    where im.institution_id=v_institution_id and im.user_id=v_actor
      and im.status='active' and im.membership_role='administrator'
  ) and not exists (
    select 1 from public.platform_group_members gm
    where gm.group_id=p_group_id and gm.user_id=v_actor and gm.status='active'
      and gm.membership_role in ('teacher','tutor','staff','administrator')
  ) then
    raise exception 'active teaching assignment required to view this class roster' using errcode = '42501';
  end if;

  return query
    select
      gm.user_id,
      coalesce(nullif(btrim(p.display_name),''),nullif(btrim(p.username),''),'Student')::text,
      gm.membership_role,
      gm.status,
      gm.created_at
    from public.platform_group_members gm
    left join public.profiles p on p.id=gm.user_id
    where gm.group_id=p_group_id and gm.status='active'
    order by gm.membership_role,gm.created_at,gm.user_id;
end;
$roster$;

revoke all on function public.create_platform_institution(text,text,text) from public, anon;
revoke all on function public.create_platform_group(uuid,text,text,uuid) from public, anon;
revoke all on function public.create_platform_institution_invite(uuid,text,text,uuid,timestamptz) from public, anon;
revoke all on function public.redeem_platform_institution_invite(text) from public, anon;
revoke all on function public.revoke_platform_institution_invite(uuid,uuid) from public, anon;
revoke all on function public.set_platform_membership_status(uuid,uuid,text,uuid) from public, anon;
revoke all on function public.list_platform_group_roster(uuid) from public, anon;

grant execute on function public.create_platform_institution(text,text,text) to authenticated;
grant execute on function public.create_platform_group(uuid,text,text,uuid) to authenticated;
grant execute on function public.create_platform_institution_invite(uuid,text,text,uuid,timestamptz) to authenticated;
grant execute on function public.redeem_platform_institution_invite(text) to authenticated;
grant execute on function public.revoke_platform_institution_invite(uuid,uuid) to authenticated;
grant execute on function public.set_platform_membership_status(uuid,uuid,text,uuid) to authenticated;
grant execute on function public.list_platform_group_roster(uuid) to authenticated;
